/// <summary>
/// The <c>ConDemoPackProcessGuidePromptContainerStep</c> class represents the screen that asks
/// the worker to scan the container that is packed.
/// </summary>
[ProcessGuideStepName(classStr(ConDemoPackProcessGuidePromptContainerStep))]
public class ConDemoPackProcessGuidePromptContainerStep extends ProcessGuideStep
{
}

Method.Source:
/// <summary>
/// Gets the name of the page builder that builds the screen of this step.
/// </summary>
/// <returns>
/// The name of the page builder class.
/// </returns>
protected ProcessGuidePageBuilderName pageBuilderName()
{
    return classStr(ConDemoPackProcessGuidePromptContainerPageBuilder);
}

/// <summary>
/// Specifies if the step is completed.
/// </summary>
/// <returns>
/// true, if the worker confirmed a container; otherwise, false.
/// </returns>
protected boolean isComplete()
{
    WhsrfPassthrough pass = controller.parmSessionState().parmPass();

    return pass.lookupStr(ProcessGuideDataTypeNames::ContainerId) != '';
}
